//
// Storage class
// ----------------------------------------------
export default class Storage {
    constructor(namespace) {
        this.available = true;
        this.data = {};
        this.namespace = namespace;
        this.available = typeof localStorage !== 'undefined';
        if (!this.available)
            return;
        this.preload();
    }
    //
    // preload all data
    // ----------------------------------------------
    preload() {
        if (!this.available)
            return false;
        const raw = localStorage.getItem(this.namespace) || '{}';
        this.data = JSON.parse(raw);
    }
    //
    // Get data 
    // ----------------------------------------------
    get(key) {
        if (!this.available)
            return false;
        return this.data[key];
    }
    //
    // Save data 
    // ----------------------------------------------
    set(key, value) {
        if (!this.available)
            return false;
        this.data[key] = value;
        localStorage.setItem(this.namespace, JSON.stringify(this.data));
    }
}
